  AddOp '8b2d19f' @{title=$s.trustEye}; AddOp '7872ddb' @{title=$s.trustTitle}; AddOp '0cab69f' @{title=$s.trustSub}; AddOp 'a7c8c10' @{icon_list=@(@{text=$s.trust[0];selected_icon=@{value='fas fa-check';library='fa-solid'};_id='t1'},@{text=$s.trust[1];selected_icon=@{value='fas fa-check';library='fa-solid'};_id='t2'},@{text=$s.trust[2];selected_icon=@{value='fas fa-check';library='fa-solid'};_id='t3'})}; AddOp 'dc27b4e' @{image=$image}
  AddOp 'd23f129' @{title='REPRESENTATIVE SCENARIOS'}; AddOp 'af9045d' @{title="Common $($s.h1.Replace(' in Dallas-Fort Worth','')) Situations Across Dallas-Fort Worth"}; AddOp 'db3259a' @{editor='<p>These examples describe plausible project situations, not claimed customer jobs. They show how property conditions and customer priorities can change the recommended next step.</p>'}; $storyIds=@('6f2ddbb','93107df','dc9463b','fe1841a'); for($i=0;$i-lt4;$i++){AddOp $storyIds[$i] @{editor="<h4>$($s.scenarios[$i][0])</h4><p>$($s.scenarios[$i][1])</p>"}}
  AddOp '6b5ea5f' @{title='RELATED SERVICES'}; AddOp 'a960571' @{title='Connected Solar and Electrical Services'}; AddOp 'c60f4f6' @{editor="<p>$($s.relatedIntro)</p>"}; AddOp '68e12ad' @{editor='<p>Explore all <a href="/services/">Solar Repair Pros services</a>, review the <a href="/service-areas/">Dallas-Fort Worth service areas</a>, or return to the <a href="/">Solar Repair Pros home page</a>.</p>'}
  AddOp 'e9213de' @{title='GOOD TO KNOW'}; AddOp 'aa7ed50' @{title=$s.authority}; AddOp '97224d4' @{editor=$s.authorityCopy}
